-- Six-tier balanced puzzle pool and generator; already applied to production.
-- Apply after percentage-association-scoring.sql when rebuilding.

-- Hosted migration 20261124235728: ascent_prevalidated_all_six_tiers
create table ascent_game.balanced_boards_v7 (
 target text not null, clues text[] not null check(cardinality(clues)=6), phrase_count smallint not null check(phrase_count in (2,3)), quality smallint not null, witnesses text[] not null check(cardinality(witnesses)=6), primary key(target,clues)
);
alter table ascent_game.balanced_boards_v7 enable row level security;
revoke all on ascent_game.balanced_boards_v7 from public,anon,authenticated;

-- Hosted migration 20261124235751: ascent_enforce_all_six_match_tiers
create or replace function ascent_game.generate_varied_climb(seed text, player uuid)
returns jsonb language plpgsql stable set search_path='' as $fn$
declare prior_clues text[]; prior_signatures text[]; used_clues text[]:='{}'; used_targets text[]:='{}'; pitches jsonb:='[]'; selected record; phrase_count int; i int; shuffled text[];
begin
 select coalesce(array_agg(distinct clue),'{}') into prior_clues
 from ascent_game.runs r join ascent_game.circuits c on c.route_id=case when r.scope like 'practice:%' then r.scope else 'daily:'||to_char(r.day,'YYYY-MM-DD') end
 cross join lateral jsonb_array_elements(c.boards) p cross join lateral jsonb_array_elements_text(p->'clues') clue
 where r.ticket=player and c.route_id<>seed;
 select coalesce(array_agg(distinct ascent_game.pitch_signature(p)),'{}') into prior_signatures
 from ascent_game.runs r join ascent_game.circuits c on c.route_id=case when r.scope like 'practice:%' then r.scope else 'daily:'||to_char(r.day,'YYYY-MM-DD') end cross join lateral jsonb_array_elements(c.boards) p
 where r.ticket=player and c.route_id<>seed;
 for i in 0..4 loop
  phrase_count:=2+case when i=mod(get_byte(decode(md5(seed),'hex'),1),5) and mod(get_byte(decode(md5(seed),'hex'),0),2)=1 then 1 else 0 end;
  with personal as (
   select p->>'target' target,count(*) n from ascent_game.runs r join ascent_game.circuits c on c.route_id=case when r.scope like 'practice:%' then r.scope else 'daily:'||to_char(r.day,'YYYY-MM-DD') end cross join lateral jsonb_array_elements(c.boards) p where r.ticket=player and c.route_id<>seed group by 1
  ), overall as (
   select p->>'target' target,count(*) n from ascent_game.circuits c cross join lateral jsonb_array_elements(c.boards) p where c.lex_version=7 group by 1
  )
  select b.target,b.clues into selected
  from ascent_game.balanced_boards_v7 b left join personal u on u.target=b.target left join overall g on g.target=b.target
  where b.phrase_count=phrase_count and b.target<>all(used_targets) and not(b.clues && used_clues)
  and not(ascent_game.pitch_signature(jsonb_build_object('clues',b.clues))=any(prior_signatures))
  and not exists(select 1 from ascent_game.published_pitches p where p.signature=ascent_game.pitch_signature(jsonb_build_object('clues',b.clues)))
  and not exists(select 1 from unnest(b.witnesses) with ordinality w(word,n) where (select count(*) from jsonb_object_keys(ascent_game.match_guess(7,b.clues,w.word)))<>w.n)
  order by coalesce(u.n,0), (select count(*) from unnest(b.clues) c where c=any(prior_clues)),coalesce(g.n,0),md5(seed||i||b.target||array_to_string(b.clues,',')),b.quality desc
  limit 1;
  if not found then
   -- Allow repeats of individual clues only when necessary, never a previously seen board.
   select b.target,b.clues into selected from ascent_game.balanced_boards_v7 b
   where b.target<>all(used_targets)
   and not(ascent_game.pitch_signature(jsonb_build_object('clues',b.clues))=any(prior_signatures))
   and not exists(select 1 from ascent_game.published_pitches p where p.signature=ascent_game.pitch_signature(jsonb_build_object('clues',b.clues)))
   and not exists(select 1 from unnest(b.witnesses) with ordinality w(word,n) where (select count(*) from jsonb_object_keys(ascent_game.match_guess(7,b.clues,w.word)))<>w.n)
   order by (select count(*) from unnest(b.clues) c where c=any(used_clues)),(select count(*) from unnest(b.clues) c where c=any(prior_clues)),(b.phrase_count<>phrase_count),md5(seed||i||b.target||array_to_string(b.clues,',')) limit 1;
  end if;
  if not found then raise exception 'No unused puzzle with all six match tiers is available';end if;
  select array_agg(c order by md5(seed||i||'position'||c)) into shuffled from unnest(selected.clues) c;
  pitches:=pitches||jsonb_build_array(jsonb_build_object('target',selected.target,'clues',shuffled));
  used_clues:=used_clues||selected.clues;used_targets:=array_append(used_targets,selected.target);
 end loop;
 return pitches;
end;$fn$;
revoke all on function ascent_game.generate_varied_climb(text,uuid) from public,anon,authenticated;
do $patch$
declare d text; n text;
begin
 select pg_get_functiondef('public.ascent_top_answers(uuid,date,date,uuid,integer)'::regprocedure) into d;
 n:=replace(d,'from matches order by points desc,word collate "C" limit 100','from matches
), tier_ranked as (
 select *, row_number() over(partition by hits order by points desc,word collate "C") tier_rank from ranked
), chosen as (
 select * from tier_ranked order by (tier_rank=1) desc,points desc,word collate "C" limit 100');
 n:=replace(n,'''[]'') from ranked;','''[]'') from chosen;');
 if n=d or n not like '%from chosen;%' then raise exception 'Answer review patch mismatch';end if;
 execute n;
end;$patch$;

